    qysj_tungumian: {
        equipSkill: true,
        audio: 'ext:猫猫叹气/audio:2',
        trigger: {
            source: 'damageBegin',
            player: 'damageBegin',
        },
        filter(event, player) {
            return event.num > 0;
        },
        forced: true,
        content() {
            'step 0';
            event.count = 3;
            ('step 1');
            event.cards = get.cards(4);
            game.cardsGotoOrdering(event.cards);
            var red = 0,
                black = 0;
            for (let c of event.cards) {
                if (get.color(c) == 'red') {
                    red++;
                } else {
                    black++;
                }
            }
            var dialog = ui.create.dialog(get.prompt('qysj_tungumian'), event.cards, '黑色:获得所有黑色牌<br>红色:获得所有红色牌', 'hidden');
            var list = [];
            if (black > 0) list.push('黑色');
            if (red > 0) list.push('红色');
            list.push('取消');
            player
                .chooseControl(list)
                .set('ai', function () {
                    var red = 0,
                        black = 0;
                    for (let c of event.cards) {
                        if (get.color(c) == 'red') {
                            red++;
                            red += get.value(c);
                        } else {
                            black++;
                            black += get.value(c);
                        }
                    }
                    for (let c of event.cards) {
                        if (get.color(c) == 'red' && c.name == 'du') {
                            red = 0;
                            break;
                        }
                        if (get.color(c) == 'black' && c.name == 'du') {
                            black = 0;
                            break;
                        }
                    }
                    if (red > 0 || black > 0) {
                        if (red >= black) return '红色';
                        else return '黑色';
                    }
                    return '取消';
                })
                .set('dialog', dialog);
            ('step 2');
            if (result.control != '取消') {
                var card = [];
                for (let c of event.cards) {
                    if (result.control == '红色' && get.color(c) == 'red') card.push(c);
                    if (result.control == '黑色' && get.color(c) == 'black') card.push(c);
                }
                if (card.length) player.gain(card, 'draw2');
            }
            if (trigger.source && trigger.source == trigger.player && event.count < 5) {
                event.goto(1);
                event.count = 190;
            }
        },
    },
