            player.discard(cards[0]);
            var s = cards[0].suit;
            var name = 'qysj_hongshaoniuroumian';
            if (s == 'spade') name = 'qysj_laniuroumian';
            if (s == 'club') name = 'qysj_tungumian';
            if (s == 'heart') name = 'qysj_jitangmian';
