    qysj_fangzhu: {
        audio: 'refangzhu',
        trigger: { player: 'damageEnd' },
        filter(event, player) {
            return event.num > 0;
        },
        forced: true,
        content() {
            'step 0';
            event.count = Math.min(trigger.num, 9);
            ('step 1');
            var list = ['翻面', '弃置' + get.cnNumber(player.getDamagedHp()) + '张牌', '摸' + get.cnNumber(player.getDamagedHp()) + '张牌', '失去一点体力'];
            for (var i = 0; i < list.length; i++) {
                list[i] = [i, list[i]];
            }
            var next = player.chooseButton(['放逐:请选择至多三项', [list, 'textbutton']]);
            next.set('selectButton', [1, 3]);
            next.set('filterButton', function (button) {
                var player = _status.event.player;
                var event = _status.event.getTrigger();
                if ([1, 2].includes(button.link)) return player.isDamaged();
                return true;
            });
            next.set('ai', function (button) {
                var player = _status.event.player;
                var event = _status.event.getTrigger();
                if (
                    game.hasPlayer(function (current) {
                        return get.attitude(player, current) > 0 && current.isTurnedOver();
                    })
                ) {
                    if ([0, 2].includes(button.link)) return 5;
                    else return 0;
                } else if (
                    game.hasPlayer(function (current) {
                        return get.attitude(player, current) < 0;
                    })
                ) {
                    if (
                        game.hasPlayer(function (current) {
                            return get.attitude(player, current) < 0 && !current.isTurnedOver();
                        }) &&
                        button.link == 0
                    )
                        return 3;
                    if ([1, 3].includes(button.link)) return 3;
                } else if (
                    game.hasPlayer(function (current) {
                        return get.attitude(player, current) > 0;
                    }) &&
                    button.link == 2
                )
                    return 2;
                return 0;
            });
            ('step 2');
            if (!result.bool) {
                event.finish();
                return;
            }
            event.links = result.links;
            var prompt = '';
            if (result.links.includes(0)) prompt += '翻面、';
            if (result.links.includes(1)) prompt += '弃置' + get.cnNumber(player.getDamagedHp()) + '张牌、';
            if (result.links.includes(2)) prompt += '摸' + get.cnNumber(player.getDamagedHp()) + '张牌、';
            if (result.links.includes(3)) prompt += '失去一点体力、';
            prompt = prompt.slice(0, prompt.length - 1);
            player
                .chooseTarget('放逐:令一名角色' + prompt, true, function (card, player, target) {
                    return true;
                })
                .set('ai', function (target) {
                    var att = get.attitude(player, target);
                    if (event.links.includes(0)) {
                        if (att > 0 && target.isTurnedOver()) return att;
                        else if (att < 0 && !target.isTurnedOver()) return -att;
                        else return 0;
                    } else {
                        if (event.links.includes(2)) return att;
                        else return -att;
                    }
                    return 0;
                });
            ('step 3');
            if (result.bool) {
                var target = result.targets[0];
                event.count--;
                var map = [
                    function (player, target) {
                        target.turnOver();
                    },
                    function (player, target) {
                        target.chooseToDiscard('he', true, player.getDamagedHp());
                    },
                    function (player, target) {
                        target.draw(player.getDamagedHp());
                    },
                    function (player, target) {
                        target.loseHp();
                    },
                ];
                for (var i = 0; i < event.links.length; i++) {
                    map[event.links[i]](player, target);
                }
            }
            if (event.count > 0) event.goto(1);
        },
        ai: {
            maixie: true,
            maixie_defend: true,
        },
    },
