    xdz_shuiyaox: {
        trigger: {
            player: 'phaseZhunbeiBegin',
            global: 'gainEnd',
        },
        forced: true,
        filter(event, player, name) {
            if (
                !game.hasPlayer(function (current) {
                    return [current.name, current.name1, current.name2].includes('xdz_shuilinglingx') && current.isAlive();
                })
            )
                return false;
            if (name == 'phaseZhunbeiBegin')
                return (
                    !player.storage.xdz_shuiyaox ||
                    (player.storage.xdz_shuiyaox &&
                        game.hasPlayer(function (current) {
                            return [current.name, current.name1, current.name2].includes('xdz_shuilinglingx') && current.isDamaged();
                        }))
                );
            return player.storage.shuiyaox && player.storage.shuiyaox == event.player;
        },
        content() {
            'step 0';
            var shui = game.findPlayer(function (current) {
                return [current.name, current.name1, current.name2].includes('xdz_shuilinglingx');
            });
            var choose = event.triggername;
            if (choose == 'gainEnd') {
                event.finish();
                if (shui) {
                    player.line(shui, 'ice');
                    shui.draw();
                }
            } else {
                if (player.storage.xdz_shuiyaox) {
                    event.finish();
                    if (shui) {
                        player.line(shui, 'ice');
                        shui.recover();
                    }
                } else {
                    player.chooseTarget(
                        '【水妖】',
                        '选择一名敌方角色,令水灵灵将体力值、体力值上限调整至与其相同并获得其武将牌上所有技能.',
                        true,
                        function (card, player, target) {
                            return target.isEnemiesOf(player) && target.isAlive() && ![target.name, target.name1, target.name2].includes('xdz_shuilinglingx');
                        },
                        function (target) {
                            return 1 + Math.random();
                        }
                    );
                }
            }
            event.count = shui;
            ('step 1');
            if (result.bool) {
                var target = result.targets[0];
                var maxHp = target.maxHp;
                var hp = target.hp;
                var shuilingling = event.count;
                var name = target.name;
                var name2 = target.name2;
                var skills = [];
                if (!target.isUnseen(0)) skills.addArray(lib.character[name][3]);
                if (name2 && !target.isUnseen(1)) skills.addArray(lib.character[name2][3]);
                if (shuilingling) {
                    player.line(target, 'ice');
                    if (skills.length) {
                        for (var j = 0; j < skills.length; j++) {
                            if (lib.translate[skills[j] + '_info'] && lib.skill[skills[j]] && !lib.skill[skills[j]].unique && !player.hasSkill(skills[j])) {
                                shuilingling.addSkillLog(skills[j]);
                            }
                        }
                    }
                    shuilingling.maxHp = maxHp;
                    shuilingling.hp = hp;
                    shuilingling.update();
                    game.log('#b' + get.translation(shuilingling), '的体力值上限调整为', '#y' + maxHp);
                    game.log('#b' + get.translation(shuilingling), '的体力值调整为', '#y' + hp);
                    shuilingling.storage.yanmox = target;
                    player.storage.shuiyaox = target;
                    player.storage.xdz_shuiyaox = true;
                }
            }
        },
    },
