    xdz_huanzhenx: {
        trigger: { player: ['phaseZhunbeiBegin', 'phaseJieshuBegin'] },
        forced: true,
        filter(event, player) {
            return (
                event.name == 'phaseZhunbei' ||
                game.hasPlayer(function (current) {
                    return current.hasSkill('xdz_huanzhenx_shu');
                })
            );
        },
        logTarget(event, player) {
            return game.filterPlayer(function (current) {
                if (event.name == 'phaseZhunbei') return current != player;
                else return current.hasSkill('xdz_huanzhenx_shu');
            });
        },
        content() {
            'step 0';
            event.num = 0;
            event.targets = game
                .filterPlayer(function (current) {
                    return current != player;
                })
                .sortBySeat();
            if (trigger.name == 'phaseJieshu')
                event.targets = game
                    .filterPlayer(function (current) {
                        return current.hasSkill('xdz_huanzhenx_shu');
                    })
                    .sortBySeat();
            ('step 1');
            if (event.num < targets.length) {
                ui.clear();
                var target = targets[event.num];
                event.target = target;
                if (trigger.name == 'phaseZhunbei') {
                    var list = ['maxHp'];
                    if (target.isDamaged()) list.add('hp');
                    if (target.hp > 1) list.add('-hp');
                    if (target.maxHp > 1 && player.getEnemies().includes(target)) list.add('-maxHp');
                    list = list.randomGet();
                    var nam = [];
                    if (list == 'maxHp') nam = [0, 1, 2, 3];
                    if (list == 'hp') {
                        if (target.getDamagedHp() > 2) nam = [0, 1, 2, 3];
                        else {
                            for (var i = 0; i < target.getDamagedHp() + 1; i++) {
                                nam.add(i);
                            }
                        }
                    }
                    if (list == '-hp') {
                        if (target.hp > 3) nam = [0, 1, 2, 3];
                        else {
                            for (var i = 0; i < target.hp; i++) {
                                nam.add(i);
                            }
                        }
                    }
                    if (list == '-maxHp') {
                        if (target.maxHp > 3) nam = [0, 1, 2, 3];
                        else {
                            for (var i = 0; i < target.maxHp; i++) {
                                nam.add(i);
                            }
                        }
                    }
                    nam = nam.randomGet();
                    if (nam == 0) {
                        game.log(target, '未陷入幻阵');
                        target.popup('未陷入幻阵', 'metal');
                    } else {
                        target.addSkill('xdz_huanzhenx_shu');
                        if (list == 'maxHp') {
                            target.maxHp = target.maxHp + nam;
                            game.log(target, '的体力上限', '#g+' + nam);
                            target.popup('上限+' + nam, 'wood');
                            target.storage.xdz_huanzhenx_shu = ['体力上限', '+', nam];
                        }
                        if (list == '-maxHp') {
                            target.maxHp = target.maxHp - nam;
                            game.log(target, '的体力上限', '#g-' + nam);
                            target.popup('上限-' + nam, 'fire');
                            target.storage.xdz_huanzhenx_shu = ['体力上限', '-', nam];
                        }
                        if (list == 'hp') {
                            target.hp = target.hp + nam;
                            game.log(target, '的体力值', '#g+' + nam);
                            target.popup('体力+' + nam, 'wood');
                            target.storage.xdz_huanzhenx_shu = ['体力值', '+', nam];
                        }
                        if (list == '-hp') {
                            target.hp = target.hp - nam;
                            game.log(target, '的体力值', '#g-' + nam);
                            target.popup('体力-' + nam, 'fire');
                            target.storage.xdz_huanzhenx_shu = ['体力值', '-', nam];
                        }
                    }
                    target.update();
                } else {
                    var storage = target.storage.xdz_huanzhenx_shu;
                    if (storage[0] == '体力上限') {
                        if (storage[1] == '+') {
                            target.maxHp = target.maxHp - storage[2];
                            game.log(target, '的体力上限', '#g-' + storage[2]);
                            target.popup('上限-' + storage[2], 'fire');
                        } else {
                            target.maxHp = target.maxHp + storage[2];
                            game.log(target, '的体力上限', '#g+' + storage[2]);
                            target.popup('上限+' + storage[2], 'wood');
                        }
                    } else {
                        if (storage[1] == '+') {
                            target.hp = target.hp - storage[2];
                            game.log(target, '的体力值', '#g-' + storage[2]);
                            target.popup('体力-' + storage[2], 'fire');
                        } else {
                            target.hp = target.hp + storage[2];
                            game.log(target, '的体力值', '#g+' + storage[2]);
                            target.popup('体力+' + storage[2], 'wood');
                        }
                    }
                    target.removeSkill('xdz_huanzhenx_shu');
                    delete target.storage.xdz_huanzhenx_shu;
                    target.update();
                    if (target.maxHp < 1) target.die();
                    if (target.hp < 1) target.dying({});
                }
                var max = target.maxHp;
                if (target.hp > target.maxHp) target.hp = max;
                event.num++;
                event.redo();
            }
            ('step 2');
            ui.clear();
        },
        subSkill: {
            shu: {
                mark: true,
                marktext: '幻',
                intro: {
                    name: '陷入幻阵',
                    content(storage, player) {
                        if (storage) return storage[0] + storage[1] + storage[2];
                    },
                    markcount(player) {
                        return false;
                    },
                },
            },
        },
    },
