            thundersha.node.image.setBackgroundImage('extension/猫猫叹气/image/东风/' + doushou[2] + '.png');
            cards.push(sha);
            cards.push(firesha);
            cards.push(thundersha);
            if (result.bool) {
                player.gain(cards, 'draw2').gaintag.add('mym_wuxiandou');
            } else player.gain(cards, 'draw2').gaintag.add('mym_buzhandou');
            ('step 9');
            //   player.popup('掷骰子','dong0');
            player.throwDice();
            ('step 10');
            game.log(player, '掷骰子点数为', '#y' + num);
            event.finish();
            player.draw(num);
            ('step 11');
            player.chooseTarget(
                '选择一个猜拳的目标',
                true,
                function (card, player, target) {
                    if (target == player) return false;
                    return true;
                },
                function (target) {
                    return Math.random();
                }
            );
            ('step 12');
            if (result.bool) event.target = result.targets[0];
            ('step 13');
            //  player.popup('猜拳','dong0');
            player.chooseToPSS(event.target);
            ('step 14');
            if (result.tie) event.goto(13);
            else if (result.bool) player.chooseUseTarget({ name: 'wanjian' }, true);
            else {
                var name = 'mym_baguaqizhen';
                if (!lib.card[name]) {
                    lib.card[name] = get.copy(lib.skill.mym_youxi[name]);
                    lib.translate[name] = get.translation(name);
                    lib.translate[name + '_info'] = get.translation(name + '_info');
                }
                player.useCard(game.createCard(name), player);
            }
            ('step 15');
            if (result.control == '确定') {
                player.storage.mym_youxi = 8;
                player.loseHp();
                game.log(player, '重置了所有', '#y小游戏');
                delete player.storage.xiaoyouxi;
                event.goto(0);
            }
