    mym_wuxiandou: {
        mod: {
            ignoredHandcard(card, player) {
                if (card.hasGaintag('mym_buzhandou')) {
                    return true;
                }
            },
            cardDiscardable(card, player, name) {
                if (name == 'phaseDiscard' && card.hasGaintag('mym_buzhandou')) {
                    return false;
                }
            },
            cardUsable(card, player, num) {
                if (!card.cards) return;
                for (var i of card.cards) {
                    if (!i.hasGaintag('mym_wuxiandou')) return;
                }
                return Infinity;
            },
            targetInRange(card, player) {
                if (!card.cards) return;
                for (var i of card.cards) {
                    if (!i.hasGaintag('mym_wuxiandou')) return;
                }
                return true;
            },
            aiOrder(player, card, num) {
                if (get.itemtype(card) == 'card' && card.hasGaintag('mym_wuxiandou')) return num - 0.1;
            },
        },
    },
