                    var names = ['mym_yongshengqiongjiang', 'mym_datianshiqixi', 'mym_xiaoemomeiyan', 'zhiliaobo'];
                    if (ui.selected.buttons.length && names.includes(ui.selected.buttons[0].link[2]) && names.includes(name)) return 0;
                    if (player.getDamagedHp() > 2 && name == 'mym_yongshengqiongjiang') return 50;
                    if (player.getDamagedHp() > 1 && name == 'mym_xiaoemomeiyan') return 30;
                    if (player.isDamaged() && name == 'zhiliaobo') return 30;
                    if (player.hp < 3) {
                        if (['mym_datianshiqixi', 'mym_xiaoemomeiyan', 'mym_yongshengqiongjiang', 'zhiliaobo'].includes(name)) return 20;
                    }
                    if (player.countCards('h') > 7 && name == 'mym_bazhuajuguai') return 0;
                    if (player.countCards('h') < 8 && 8 - player.countCards('h') > 3 && name == 'mym_bazhuajuguai') return 15 + (8 - player.countCards('h'));
