    qmyy_keling2: {
        trigger: {
            source: 'damageEnd',
        },
        filter(event, player) {
            return event.num > 0 && event.player.isAlive() && player != event.player && player.storage.keling && player.storage.keling.includes(event.player);
        },
        forced: true,
        logTarget: 'player',
        _priority: -18,
        //  direct:true,
        content() {
            'step 0';
            player.storage.keling.remove(trigger.player);
            if (!player.storage.keling.length) delete player.storage.keling;
            if (!trigger.player.isDamaged()) return;
            trigger.player.chooseBool('克零:是否将体力值回复至体力值上限？').set('ai', function () {
                return true;
            });
            ('step 1');
            if (result.bool) trigger.player.hp = trigger.player.maxHp;
            ('step 2');
            ('step 3');
            var next = game.createEvent('dying');
            next.player = trigger.player;
            next.reason = trigger;
            next.source = player;
            next.setContent(lib.skill.qmyy_keling2.dyingx);
        },
        dyingx() {
            'step 0';
            event.forceDie = true;
            event.ori = player.hp;
            if (player.isDying()) {
                event.finish();
                return;
            }
            _status.dying.unshift(player);
            game.broadcast(function (list) {
                _status.dying = list;
            }, _status.dying);
            event.trigger('dying');
            game.log(player, '濒死');
            ('step 1');
            if (player.hp > event.ori) {
                _status.dying.remove(player);
                game.broadcast(function (list) {
                    _status.dying = list;
                }, _status.dying);
                event.finish();
            } else if (!event.skipTao) {
                var next = game.createEvent('_save');
                var start = false;
                var starts = [_status.currentPhase, event.source, event.player, game.me, game.players[0]];
                for (var i = 0; i < starts.length; i++) {
                    if (get.itemtype(starts[i]) == 'player') {
                        start = starts[i];
                        break;
                    }
                }
                next.player = start;
                next._trigger = event;
                next.triggername = '_save';
                next.ori = event.ori;
                next.forceDie = true;
                next.setContent(lib.skill.qmyy_keling2.savex);
            }
            ('step 2');
            _status.dying.remove(player);
            game.broadcast(function (list) {
                _status.dying = list;
            }, _status.dying);
            if (player.hp <= event.ori && !player.nodying) player.die(event.reason);
        },
        savex() {
            'step 0';
            event.dying = trigger.player;
            if (!event.acted) event.acted = [];
            ('step 1');
            if (trigger.player.isDead()) {
                event.finish();
                return;
            }
            event.acted.push(player);
            var str = get.translation(trigger.player) + '濒死,是否帮助？';
            var str2 = '当前体力:' + trigger.player.hp;
            if (lib.config.tao_enemy && event.dying.side != player.side && lib.config.mode != 'identity' && lib.config.mode != 'guozhan' && !event.dying.hasSkillTag('revertsave')) {
                event._result = { bool: false };
            } else if (player.canSave(event.dying)) {
                player.chooseToUse({
                    filterCard(card, player, event) {
                        event = event || _status.event;
                        return lib.filter.cardSavable(card, player, event.dying);
                    },
                    filterTarget: trigger.player,
                    prompt: str,
                    prompt2: str2,
                    type: 'dying',
                    targetRequired: true,
                    dying: event.dying,
                });
            } else {
                event._result = { bool: false };
            }
            ('step 2');
            if (result.bool) {
                if (trigger.player.hp <= event.ori && !trigger.player.nodying && trigger.player.isAlive() && !trigger.player.isOut() && !trigger.player.removed) event.goto(0);
                else trigger.untrigger();
            } else {
                for (var i = 0; i < 20; i++) {
                    if (event.acted.includes(event.player.next)) {
                        break;
                    } else {
                        event.player = event.player.next;
                        if (!event.player.isOut()) {
                            event.goto(1);
                            break;
                        }
                    }
                }
            }
        },
    },
