    boss_scyinghun: {
        content() {
            'step 0';
            lib.translate.boss_scyinghun = get.translation('yinghun');
            lib.translate.boss_scyinghun_info = get.translation('yinghun_info');
            player
                .chooseTarget(get.prompt2('boss_scyinghun'), function (card, player, target) {
                    return player != target;
                })
                .set('ai', function (target) {
                    var player = _status.event.player;
                    if (player.maxHp - player.hp == 1 && target.countCards('he') == 0) {
                        return 0;
                    }
                    if (get.attitude(_status.event.player, target) > 0) {
                        return 10 + get.attitude(_status.event.player, target);
                    }
                    if (player.maxHp - player.hp == 1) {
                        return -1;
                    }
                    return 1;
                });
            ('step 1');
            if (result.bool) {
                event.num = player.maxHp - player.hp;
                if (player.countCards('e') >= player.hp) {
                    event.num = player.maxHp;
                }
                event.target = result.targets[0];
                if (event.num == 1) {
                    event.directcontrol = true;
                } else {
                    var str1 = '摸' + get.cnNumber(event.num, true) + '弃一';
                    var str2 = '摸一弃' + get.cnNumber(event.num, true);
                    player
                        .chooseControl(str1, str2, function (event, player) {
                            return _status.event.choice;
                        })
                        .set('choice', get.attitude(player, event.target) > 0 ? str1 : str2);
                    event.str = str1;
                }
            } else {
                event.finish();
            }
            ('step 2');
            if (event.directcontrol || result.control == event.str) {
                event.target.draw(event.num);
                event.target.chooseToDiscard(true, 'he');
            } else {
                event.target.draw();
                event.target.chooseToDiscard(event.num, true, 'he');
            }
        },
        inherit: 'yinghun',
        audio: 'ext:猫猫叹气/audio:2',
    },
