                    if (name == 'damageBegin') return event.num > 0 && event.player.hasSkill('yjcksgzz_yinshi_baiwan') && event.card && event.player.storage.yjcksgzz_yinshi_baiwan && event.card.name == event.player.storage.yjcksgzz_yinshi_baiwan && (!event.source || event.source != player);
                    if (name == 'useCard') return event.player.hasSkill('yjcksgzz_yinshi_heiwan') && event.player.storage.yjcksgzz_yinshi_heiwan && event.card.name == event.player.storage.yjcksgzz_yinshi_heiwan;
