                    if (trigger.name == 'phaseJieshu') {
                        result.targets[i].storage.yjcksgzz_yinshi_heiwan = event.cardname;
                        result.targets[i].addSkill('yjcksgzz_yinshi_heiwan');
                        result.targets[i].markSkill('yjcksgzz_yinshi_heiwan');
                    }
