    shenggj_xiangzhi: {
        audio: 'ext:猫猫叹气/audio:2',
        trigger: { player: 'phaseDrawBegin1' },
        filter(event, player) {
            return !event.numFixed;
        },
        content() {
            'step 0';
            trigger.changeToZero();
            event.cards = get.cards(3);
            game.cardsGotoOrdering(event.cards);
            player.showCards(event.cards);
            var red = 0,
                black = 0;
            for (let c of event.cards) {
                if (get.color(c) == 'red') {
                    red++;
                } else {
                    black++;
                }
            }
            var dialog = ui.create.dialog('【相知】', '选择一种颜色的牌获得', event.cards, 'hidden');
            var list = [];
            if (black > 0) list.push('黑色');
            if (red > 0) list.push('红色');
            //  list.push('取消');
            player
                .chooseControl(list)
                .set('ai', function () {
                    var red = 0,
                        black = 0,
                        redx = 0,
                        blax = 0;
                    for (let c of event.cards) {
                        if (get.color(c) == 'red') {
                            redx++;
                            red++;
                            red += get.value(c);
                        } else {
                            blax++;
                            black++;
                            black += get.value(c);
                        }
                    }
                    for (let c of event.cards) {
                        if (get.color(c) == 'red' && c.name == 'du') {
                            red = 0;
                            break;
                        }
                        if (get.color(c) == 'black' && c.name == 'du') {
                            black = 0;
                            break;
                        }
                    }
                    if (red > 0 || black > 0) {
                        if (red >= black) return '红色';
                        else return '黑色';
                    }
                    if (redx >= blax && redx > 0) return '红色';
                    return '黑色';
                })
                .set('dialog', dialog);
            ('step 1');
            var card = [],
                give = [];
            for (let c of event.cards) {
                if (result.control == '红色') {
                    if (get.color(c) == 'red') card.push(c);
                    else give.push(c);
                }
                if (result.control == '黑色') {
                    if (get.color(c) == 'black') card.push(c);
                    else give.push(c);
                }
            }
            if (card.length) player.gain(card, 'draw2');
            //	}
            if (!give.length) event.finish();
            else event.cards = give;
            ('step 2');
            var dialog = ui.create.dialog('相知', '将这些牌分配给任意其他角色', 'hidden');
            dialog.add(event.cards);
            var chooseButton = player.chooseButton([1, Infinity], dialog, true);
            chooseButton.set('ai', function (button) {
                if (ui.selected.buttons.length == 0) return 1;
                return 0;
            });
            ('step 3');
            if (result.bool) {
                for (var i of result.links) {
                    event.cards.remove(i);
                }
                event.togive = result.links.slice(0);
                player
                    .chooseTarget(
                        '将' + get.translation(result.links) + '交给一名角色',
                        true,
                        function (card, player, target) {
                            return player != target;
                        },
                        function (target) {
                            var att = get.attitude(_status.event.player, target);
                            if (_status.event.enemy) {
                                return -att;
                            } else if (att > 0) {
                                return att / (1 + target.countCards('h'));
                            } else {
                                return att / 100;
                            }
                        }
                    )
                    .set('enemy', get.value(event.togive[0], player, 'raw') < 0);
            }
            ('step 4');
            if (result.targets.length) {
                result.targets[0].gain(event.togive, 'gain2');
                player.line(result.targets[0], 'green');
                //    game.log(result.targets[0],'获得了'+get.cnNumber(event.togive.length)+'张牌');
                if (event.cards.length) event.goto(2);
            }
        },
    },
