    xspyy_choudu: {
        audio: 'ext:猫猫叹气/audio:2',
        enable: 'phaseUse',
        usable: 1,
        filterCard: true,
        filter(event, player) {
            return player.countCards('he');
        },
        content() {
            player.chooseUseTarget({ name: 'diaobingqianjiang' }, true);
        },
        ai: {
            order: 5,
            result: {
                player: 1,
            },
        },
        position: 'he',
        group: 'xspyy_choudu_dbqj',
        subSkill: {
            dbqj: {
                trigger: { player: 'useCard' },
                filter(event, player) {
                    return event.card && event.card.name == 'diaobingqianjiang';
                },
                forced: true,
                content() {
                    'step 0';
                    trigger.fixedSeat = true;
                    trigger.targets.sortBySeat();
                    player.chooseTarget(
                        get.prompt('xspyy_choudu'),
                        '你可以令' + get.translation(trigger.card) + '从任意一名角色开始结算',
                        function (card, player, target) {
                            return trigger.targets.includes(target);
                        },
                        function (target) {
                            var att = get.attitude(player, target);
                            var att2 = get.attitude(player, target.next);
                            var att3 = get.attitude(player, target.previous);
                            var att0 = get.attitude(player, target.next.next);
                            var att1 = get.attitude(player, target.previous.previous);
                            if (att > 0 && att2 > 0 && att3 > 0) {
                                if (att0 > 0 && target.previous == target) return 100;
                                if (att1 > 0 && target.next == target) return 100;
                                return att2;
                            }
                            if (att > 0 && (att2 > 0 || att3 > 0)) {
                                if (att2 > 0) return att + att2;
                                return att + att3;
                            }
                            return att;
                        }
                    );
                    ('step 1');
                    if (result.bool) {
                        var target = result.targets[0];
                        event.target = target;
                        event.target2 = target;
                        game.log(trigger.card, '从', target, '开始结算');
                        event.targetx = [];
                    } else event.finish();
                    ('step 2');
                    player
                        .chooseControl('顺时针', '逆时针', function (event, player) {
                            if (get.attitude(player, event.target.next) > 0) return '逆时针';
                            return '顺时针';
                        })
                        .set('prompt', get.translation(trigger.card) + '从' + get.translation(event.target) + '开始结算,请选择' + get.translation(trigger.card) + '的结算方向');
                    ('step 3');
                    var fangxiang = 'next';
                    if (result && result.control == '顺时针') fangxiang = 'previous';
                    game.log(trigger.card, '按', result.control, '方向结算');
                    event.count = fangxiang;
                    ('step 4');
                    if (trigger.targets.includes(event.target)) event.targetx.add(event.target);
                    ('step 5');
                    if (event.target[event.count] != event.target2) {
                        event.target = event.target[event.count];
                        event.goto(4);
                    }
                    ('step 6');
                    trigger.targets = event.targetx;
                },
            },
        },
    },
    xspyy_liduan: {
        audio: 'ext:猫猫叹气/audio:2',
        trigger: { global: 'gainAfter' },
        filter(event, player) {
            if (event.player == player) return false;
            if (_status.currentPhase == event.player) return false;
            if (!event.cards || !event.cards.length) return false;
            var num = 0;
            for (let c of event.cards) {
                if (get.type(c) == 'equip' && get.position(c) == 'h') num++;
            }
            return num > 0;
        },
        logTarget: 'player',
        content() {
            'step 0';
            var cards = [];
            for (let c of trigger.cards) {
                if (get.type(c) == 'equip' && trigger.player.getCards('h').includes(c)) cards.add(c);
            }
            event.cards = cards;
            if (!cards.length) event.finish();
            ('step 1');
            event.card = event.cards.shift();
            var next = trigger.player.chooseToUse();
            next.filterCard = function (card) {
                return event.card == card;
            };
            next.prompt = get.translation(player) + '对你发动技能【立断】,是否使用' + get.translation(event.card) + '？';
            next.prompt2 = '若你选择不使用,则你需交给' + get.translation(player) + '一张手牌';
            ('step 2');
            if (!result.bool) {
                trigger.player.chooseCard('h', true, '立断:交给' + get.translation(player) + '一张手牌');
            } else event.goto(4);
            ('step 3');
            if (result.bool) {
                trigger.player.give(result.cards, player, true);
            }
            ('step 4');
            var cardx = [];
            for (let cc of event.cards) {
                if (trigger.player.getCards('h').includes(cc)) cardx.add(cc);
            }
            event.cards = cardx;
            if (cardx.length) {
                event.goto(1);
            }
        },
    },
