    nmmj_xiefu: {
        audio: 'juezhi',
        intro: {
            mark(dialog, content, player) {
                var h = player.getCards('h', function (cardx) {
                    return cardx.hasGaintag('nmmj_xiefu');
                });
                if (h.length) {
                    dialog.addText('明置的手牌');
                    dialog.add(h);
                }
            },
            markcount(storage, player) {
                return player.countCards('h', function (cardx) {
                    return cardx.hasGaintag('nmmj_xiefu');
                });
            },
        },
        onremove(player) {
            player.removeGaintag('nmmj_xiefu');
        },
        enable: 'chooseToUse',
        viewAs: { name: 'wuxie' },
        viewAsFilter(player) {
            return player.countCards('h', function (cardx) {
                return !cardx.hasGaintag('nmmj_xiefu');
            });
        },
        filter(event, player) {
            return player.countCards('h', function (cardx) {
                return !cardx.hasGaintag('nmmj_xiefu');
            });
        },
        filterCard() {
            return false;
        },
        selectCard: -1,
        precontent() {
            'step 0';
            player
                .chooseCard('h', '明置一张手牌视为使用一张【无懈可击】', true, function (card) {
                    return !card.hasGaintag('nmmj_xiefu');
                })
                .set('ai', function (card) {
                    return 500 - get.value(card);
                });
            ('step 1');
            if (result.bool) {
                player.addGaintag(result.cards, 'nmmj_xiefu');
                player.markSkill('nmmj_xiefu');
            }
        },
        group: ['nmmj_xiefu_round'],
        ai: {
            wuxieOther: true,
        },
        subSkill: {
            round: {
                trigger: { global: 'roundStart' },
                forced: true,
                filter(event, player) {
                    return player.countCards('h', function (cardx) {
                        return cardx.hasGaintag('nmmj_xiefu');
                    });
                },
                content() {
                    'step 0';
                    var list = [],
                        list2 = ['令体力值最小的一名角色回复一点体力', '令手牌数最少的一名角色获得【亩书】直到下轮游戏开始'];
                    if (
                        game.hasPlayer(function (current) {
                            return current.isMinHp() && current.isDamaged();
                        })
                    )
                        list.push('选项一');
                    if (
                        game.hasPlayer(function (current) {
                            return current.isMinHandcard() && !current.hasSkill('nmmj_mushu');
                        })
                    )
                        list.push('选项二');
                    list.push('取消');
                    player
                        .chooseControl(list)
                        .set('choiceList', list2)
                        .set('ai', function () {
                            if (
                                list.includes('选项一') &&
                                game.hasPlayer(function (current) {
                                    return current.isMinHp() && current.isDamaged() && get.attitude(player, current) > 0;
                                })
                            )
                                return '选项一';
                            if (
                                list.includes('选项二') &&
                                game.hasPlayer(function (current) {
                                    return current.isMinHandcard() && !current.hasSkill('nmmj_mushu') && get.attitude(player, current) > 0 && current.countCards('he');
                                }) &&
                                player.countCards('h', function (cardx) {
                                    return cardx.hasGaintag('nmmj_xiefu');
                                }) < 3
                            )
                                return '选项二';
                            return '取消';
                        })
                        .set(
                            'prompt',
                            '###' +
                            get.prompt('nmmj_xiefu') +
                            '###弃置所有明置牌(' +
                            get.translation(
                                player.getCards('h', function (cardx) {
                                    return cardx.hasGaintag('nmmj_xiefu');
                                })
                            ) +
                            ')并选择一项:'
                        );
                    ('step 1');
                    if (result.control == '取消') {
                        event.finish();
                        return;
                    }
                    event.control = result.control;
                    player.chooseTarget(
                        '薤馥:' + (result.control == '选项一' ? '令体力值最小的一名角色回复一点体力' : '令手牌数最少的一名角色获得【亩书】直到下轮游戏开始'),
                        function (card, player, target) {
                            if (result.control == '选项一') return target.isMinHp() && target.isDamaged();
                            return target.isMinHandcard() && !target.hasSkill('nmmj_mushu');
                        },
                        function (target) {
                            var att = get.attitude(player, target);
                            return att;
                        }
                    );
                    ('step 2');
                    if (result.bool) {
                        player.discard(
                            player.getCards('h', function (cardx) {
                                return cardx.hasGaintag('nmmj_xiefu');
                            })
                        );
                        if (event.control == '选项一') result.targets[0].recover();
                        if (event.control == '选项二') result.targets[0].addTempSkill('nmmj_mushu', 'roundStart');
                    }
                    ('step 3');
                    if (
                        !player.countCards('h', function (cardx) {
                            return cardx.hasGaintag('nmmj_xiefu');
                        })
                    )
                        player.unmarkSkill('nmmj_xiefu');
                },
            },
        },
    },
