    nmmldw_yushou: {
        audio: 'ext:猫猫叹气/audio:2',
        derivation: ['nmmldw_jingxiang', 'nmmldw_langxiao', 'nmmldw_nuao', 'nmmldw_tengque'],
        trigger: { player: ['damageEnd', 'recoverEnd', 'loseHpEnd', 'loseMaxHpEnd'] },
        forced: true,
        filter(event, player) {
            if (event.name == 'recover') {
                for (let skill of lib.skill.nmmldw_yushou.derivation) {
                    if (player.hasSkill(skill)) {
                        return event.num > 0;
                        break;
                    }
                }
            } else {
                for (let skill of lib.skill.nmmldw_yushou.derivation) {
                    if (!player.hasSkill(skill)) {
                        if (event.name == 'loseMaxHp') {
                            return event.loseHp && event.loseHp > 0;
                        } else return event.num > 0;
                        break;
                    }
                }
            }
            return false;
        },
        content() {
            'step 0';
            event.count = Math.min(trigger.num, 9);
            if (trigger.name == 'loseMaxHp') event.count = trigger.loseHp;
            if (event.count <= 0) event.finish();
            ('step 1');
            var skills = [];
            for (let skill of lib.skill.nmmldw_yushou.derivation) {
                if (trigger.name == 'recover') {
                    if (player.hasSkill(skill)) skills.add(skill);
                } else if (!player.hasSkill(skill)) skills.add(skill);
            }
            event.count--;
            if (!skills.length) {
                event.finish();
                return;
            }
            event.skills = skills;
            player
                .chooseControl(event.skills)
                .set(
                    'choiceList',
                    event.skills.map(function (i) {
                        return '<div class="skill">【' + get.translation(lib.translate[i + '_ab'] || get.translation(i).slice(0, 2)) + '】</div><div>' + get.skillInfoTranslation(i, player) + '</div>';
                    })
                )
                .set('displayIndex', false)
                .set('prompt', '选择一个技能获得');
            ('step 2');
            var skill = result.control;
            if (trigger.name == 'recover') {
                player.removeSkill(skill);
                game.log(player, '失去了技能', '#g【' + get.translation(skill) + '】');
            } else if (!player.hasSkill(skill)) player.addSkillLog(skill);
            ('step 3');
            if (event.count > 0) {
                event.goto(1);
            }
        },
    },
