    yinbfr_duochong2: {
        audio: 'yichong',
        mark: true,
        intro: {
            mark(dialog, content, player) {
                if (_status.currentPhase && _status.currentPhase.getHistory('skipped').length) {
                    dialog.addText('当前回合结束后你可执行以下一个阶段');
                    _status.currentPhase.getHistory('skipped', function (phase) {
                        var prompt;
                        if (phase == 'phaseZhunbei') prompt = '准备阶段';
                        if (phase == 'phaseJudge') prompt = '判定阶段';
                        if (phase == 'phaseDraw') prompt = '摸牌阶段';
                        if (phase == 'phaseUse') prompt = '出牌阶段';
                        if (phase == 'phaseDiscard') prompt = '弃牌阶段';
                        if (phase == 'phaseJieshu') prompt = '结束阶段';
                        dialog.add(prompt);
                    });
                }
            },
        },
        trigger: { global: 'phaseEnd' },
        filter(event, player) {
            return event.player.getHistory('skipped').length;
        },
        _priority: 100,
        prompt2(event, player) {
            var prompt = '';
            event.player.getHistory('skipped', function (phase) {
                if (phase == 'phaseZhunbei') prompt += '准备阶段,';
                if (phase == 'phaseJudge') prompt += '判定阶段,';
                if (phase == 'phaseDraw') prompt += '摸牌阶段,';
                if (phase == 'phaseUse') prompt += '出牌阶段,';
                if (phase == 'phaseDiscard') prompt += '弃牌阶段,';
                if (phase == 'phaseJieshu') prompt += '结束阶段,';
            });
            return get.translation(event.player) + (event.player == player ? '(自己)' : '') + '本回合内跳过了' + prompt + '是否执行' + (event.player.getHistory('skipped').length > 1 ? '其中一个' : '此阶段');
        },
        content() {
            'step 0';
            var skip = [];
            event.count = [];
            trigger.player.getHistory('skipped', function (phase) {
                skip.add(phase);
                if (phase == 'phaseZhunbei') event.count.add('准备阶段');
                if (phase == 'phaseJudge') event.count.add('判定阶段');
                if (phase == 'phaseDraw') event.count.add('摸牌阶段');
                if (phase == 'phaseUse') event.count.add('出牌阶段');
                if (phase == 'phaseDiscard') event.count.add('弃牌阶段');
                if (phase == 'phaseJieshu') event.count.add('结束阶段');
            });
            if (skip.length == 1) {
                event._result = { control: skip[0] };
            } else {
                player
                    .chooseControl(event.count)
                    .set('ai', function () {
                        if (event.count.includes('摸牌阶段')) return '摸牌阶段';
                        if (event.count.includes('出牌阶段')) return '出牌阶段';
                        return 0;
                    })
                    .set('prompt', '夺宠:要执行哪个阶段？');
            }
            ('step 1');
            if (result.control == '准备阶段') result.control = 'phaseZhunbei';
            if (result.control == '判定阶段') result.control = 'phaseJudge';
            if (result.control == '摸牌阶段') result.control = 'phaseDraw';
            if (result.control == '出牌阶段') result.control = 'phaseUse';
            if (result.control == '弃牌阶段') result.control = 'phaseDiscard';
            if (result.control == '结束阶段') result.control = 'phaseJieshu';
            player[result.control]();
            player.removeSkill('yinbfr_duochong2');
        },
    },
