            if (player.storage.leicy_guanyun) num = player.storage.leicy_guanyun;
            if (num == 2) {
                list.push('sha');
                //  list.push(['基本','','sha','thunder']);
                //    list.push(['基本','','sha','ice']);
                //   list.push(['基本','','sha','stab']);
            }
