    leizj_quanhuan: {
        audio: 'ext:猫猫叹气/audio:1',
        enable: 'phaseUse',
        usable: 1,
        selectTarget: [1, Infinity],
        filterTarget(card, player, target) {
            return target != player && target.countCards('h') && get.distance(player, target) <= 1;
        },
        multiline: true,
        multitarget: true,
        content() {
            'step 0';
            event.current = player.next;
            event.targetx = [player];
            ('step 1');
            if (event.current == player) {
                event.finish();
            } else if (targets.includes(event.current)) {
                var list = [],
                    list2 = ['交给' + get.translation(player) + '一张牌,摸一张牌', '弃置一张牌停止此技能结算,视为对' + get.translation(event.targetx) + (event.targetx.length > 1 ? '依次' : '') + '使用一张【决斗】'];
                if (event.current.countCards('he')) {
                    list.push('选项一');
                    list.push('选项二');
                } else list.push('取消');
                event.current
                    .chooseControl(list)
                    .set('choiceList', list2)
                    .set('ai', function () {
                        if (list.length > 1) {
                            if (get.attitude(event.current, player) >= 0 || event.current.countCards('h', 'du')) return '选项一';
                            return '选项二';
                        }
                        return '取消';
                    })
                    .set('prompt', '劝还:请选择一项:');
            } else {
                event.current = event.current.next;
                event.redo();
            }
            ('step 2');
            event.control = result.control;
            if (result.control == '选项一') {
                event.current.chooseCard('he', '劝还:交给' + get.translation(player) + '一张牌,摸一张牌', true).set('ai', function (card) {
                    return 8 - get.value(card);
                });
                event.targetx.add(event.current);
            } else if (result.control == '选项二') {
                event.current.chooseToDiscard(true, 'he', '劝还:弃置一张牌停止此技能结算,视为对' + get.translation(event.targetx) + (event.targetx.length > 1 ? '依次' : '') + '使用一张【决斗】');
            } else {
                event.current = event.current.next;
                event.goto(1);
            }
            ('step 3');
            if (event.control == '选项一') {
                if (result.bool && result.cards && result.cards.length) {
                    player.gain(result.cards, event.current, 'giveAuto');
                    event.current.draw();
                    event.current = event.current.next;
                    event.goto(1);
                }
            }
            if (event.control == '选项二') {
                for (let tt of event.targetx) {
                    if (tt.isIn() && event.current.isIn()) event.current.useCard({ name: 'juedou' }, tt, false);
                }
            }
        },
        ai: {
            order: 8,
            result: { player: 1 },
        },
    },
