            if (result.control == '摸牌阶段') result.control = 'phaseDraw';
            if (result.control == '出牌阶段') result.control = 'phaseUse';
            if (result.control == '弃牌阶段') result.control = 'phaseDiscard';
            if (result.control == '结束阶段') result.control = 'phaseJieshu';
