                        var prompt;
                        if (phase[0] == 'phaseZhunbei') prompt = '准备阶段';
                        if (phase[0] == 'phaseJudge') prompt = '判定阶段';
                        if (phase[0] == 'phaseDraw') prompt = '摸牌阶段';
