            if (_status.connectMode)
                game.broadcastAll(function () {
                    _status.noclearcountdown = true;
                });
            event.given_map = {};
            ('step 2');
            if (event.cards.length > 1) {
                player.chooseCardButton('遗计:请选择要分配的牌', true, event.cards, [1, event.cards.length]).set('ai', function (button) {
                    if (ui.selected.buttons.length == 0) return 1;
                    return 0;
                });
            } else if (event.cards.length == 1) {
                event._result = { links: event.cards.slice(0), bool: true };
            } else {
                event.finish();
            }
            ('step 3');
            if (result.bool) {
                event.cards.removeArray(result.links);
                event.togive = result.links.slice(0);
                player
                    .chooseTarget('选择一名角色获得' + get.translation(result.links), true)
                    .set('ai', function (target) {
                        var att = get.attitude(_status.event.player, target);
                        if (_status.event.enemy) {
                            return -att;
                        } else if (att > 0) {
                            return att / (1 + target.countCards('h'));
                        } else {
                            return att / 100;
                        }
                    })
                    .set('enemy', get.value(event.togive[0], player, 'raw') < 0);
            }
            ('step 4');
            if (result.targets.length) {
                var id = result.targets[0].playerid,
                    map = event.given_map;
                if (!map[id]) map[id] = [];
                map[id].addArray(event.togive);
            }
            if (cards.length) event.goto(2);
            ('step 5');
            if (_status.connectMode) {
                game.broadcastAll(function () {
                    delete _status.noclearcountdown;
                    game.stopCountChoose();
                });
            }
            var list = [];
            for (var i in event.given_map) {
                var source = (_status.connectMode ? lib.playerOL : game.playerMap)[i];
                player.line(source, 'green');
                list.push([source, event.given_map[i]]);
            }
            game.loseAsync({
                gain_list: list,
                giver: player,
                animate: 'draw',
            }).setContent('gaincardMultiple');
            ('step 6');
            if (event.count > 0 && player.hasSkill(event.name)) {
                player.chooseBool(get.prompt2(event.name)).set('frequentSkill', event.name);
            } else event.finish();
            ('step 7');
            if (result.bool) {
                event.goto(1);
            }
